#include <LiquidCrystal_I2C.h>
#include <Keypad.h>

// ============================================================
// ЗДЕСЬ МЕНЯЙ АДРЕС ПОД СВОЙ ЗЕЛЁНЫЙ ДИСПЛЕЙ:
//   0x20 — старый синий (у тебя работал)
//   0x27 — частый у зелёных
//   0x3F — тоже бывает
// ============================================================
LiquidCrystal_I2C lcd(0x27, 16, 2);

#define buzzer   10
#define reset    A0
#define ledR     11
#define ledY     9
#define bombPin  13

const byte ROWS = 4;
const byte COLS = 3;
char keys[ROWS][COLS] = {
  {'1','2','3'},
  {'4','5','6'},
  {'7','8','9'},
  {'*','0','#'}
};
byte rowPins[ROWS] = {2,3,4,5};
byte colPins[COLS] = {6,7,8};
Keypad keypad = Keypad(makeKeymap(keys), rowPins, colPins, ROWS, COLS);

char password[8];
char masterKey[8] = "7355608";
byte indicator = 0;

bool bombArmed = false;
bool exploded  = false;

const unsigned long FUSE_MS = 30000UL;
unsigned long armTime = 0;

unsigned long lastBeep = 0;
int  beepInterval = 1000;
int  beepCount    = 0;
const int BEEP_STEPS = 40;

unsigned long errorUntil = 0;

// ============================================================
void explode() {
  if (exploded) return;
  exploded  = true;
  bombArmed = false;

  digitalWrite(bombPin, HIGH);
  digitalWrite(ledR, HIGH);
  digitalWrite(ledY, LOW);
  tone(buzzer, 800, 1000);

  lcd.clear();
  lcd.setCursor(0, 0);
  lcd.print("BOMB DETONATED");
  lcd.setCursor(0, 1);
  lcd.print("PIN 13 = HIGH");

  Serial.println("BOOM! pin 13 HIGH");
}

// ============================================================
void resetGame() {
  lcd.clear();
  lcd.setCursor(5, 0);

  indicator = 0;
  exploded  = false;
  bombArmed = false;

  digitalWrite(bombPin, LOW);
  digitalWrite(ledR, LOW);
  digitalWrite(ledY, HIGH);
  noTone(buzzer);

  beepCount    = 0;
  beepInterval = 1000;
  errorUntil   = 0;

  for (byte i = 0; i < 8; i++) password[i] = 0;
}

// ============================================================
void setup() {
  Serial.begin(9600);

  // --- ИНИЦИАЛИЗАЦИЯ КАК В ТВОЁМ РАБОЧЕМ СИНЕМ КОДЕ ---
  lcd.begin(16, 2);
  lcd.init();
  lcd.setBacklight(1);
  lcd.setCursor(5, 0);

  pinMode(buzzer,  OUTPUT);
  pinMode(ledR,    OUTPUT);
  pinMode(ledY,    OUTPUT);
  pinMode(bombPin, OUTPUT);
  pinMode(reset,   INPUT_PULLUP);

  digitalWrite(bombPin, LOW);
  digitalWrite(ledY, HIGH);
}

// ============================================================
void loop() {
  unsigned long now = millis();

  if (digitalRead(reset) == LOW) {
    delay(30);
    if (digitalRead(reset) == LOW) {
      resetGame();
      while (digitalRead(reset) == LOW) { }
    }
  }

  char key = keypad.getKey();
  if (key) Serial.println(key);

  if (key && !bombArmed && !exploded && indicator < 7 && errorUntil == 0) {
    password[indicator] = key;
    indicator++;
    lcd.print(key);
  }

  if (!bombArmed && !exploded) digitalWrite(ledY, HIGH);

  if (indicator == 7 && !bombArmed && !exploded) {
    if (!strcmp(password, masterKey)) {
      Serial.println("correct");
      lcd.clear();
      lcd.setCursor(0, 0);
      lcd.print("BOMB ARMED");
      digitalWrite(ledY, LOW);

      bombArmed    = true;
      armTime      = now;
      beepCount    = 0;
      beepInterval = 1000;
      lastBeep     = now - beepInterval;
    } else {
      Serial.println("incorrect");
      lcd.clear();
      lcd.print("incorrect");
      errorUntil = now + 2000;
      indicator  = 0;
    }
  }

  if (errorUntil && now > errorUntil) {
    errorUntil = 0;
    lcd.clear();
    lcd.setCursor(5, 0);
  }

  if (bombArmed && !exploded) {
    if (now - armTime >= FUSE_MS) {
      explode();
    }
    else if (beepCount >= BEEP_STEPS) {
      explode();
    }
    else if (now - lastBeep >= (unsigned long)beepInterval) {
      lastBeep = now;
      tone(buzzer, 800, 100);
      digitalWrite(ledR, HIGH);
      beepCount++;
      beepInterval = 1000 - beepCount * 25;
      if (beepInterval < 25) beepInterval = 25;
    }
    else {
      digitalWrite(ledR, LOW);
    }
  }
}
